import type { TroubleCodeGuide } from "./trouble-code-data";

const serviceExpress={label:"Honda ServiceExpress technical information",url:"https://techinfo.honda.com/",note:"Honda's VIN- and model-year-specific service publications, wiring diagrams and diagnostic procedures"};
const owners={label:"Honda Owners — manuals and warranty information",url:"https://mygarage.honda.com/s/manuals-search",note:"Official model-year owner manuals, maintenance information and warning-light guidance"};
const rockerBulletin={label:"Honda Service Bulletin 13-021 — P2646/P2651 or P2647/P2652",url:"https://static.nhtsa.gov/odi/tsbs/2013/SB-10052884-2696.pdf",note:"Applies to 2002–2005 Civic Si and 2012–2013 Civic except Si/Hybrid; identifies an intermittent rocker-arm oil-pressure switch branch"};
const misfireBulletin={label:"Honda Service Bulletin 19-038 — 2016–2018 Civic 1.5L misfire warranty extension",url:"https://static.nhtsa.gov/odi/tsbs/2019/MC-10165769-0002.pdf",note:"VIN eligibility required; covers specified P0300–P0304/P0172 or whirling-noise conditions and instructs technicians to address 18-137 first when applicable"};
const evapSoftware={label:"Honda Service Bulletin 14-010 — 2012 Civic P0455/P0456",url:"https://static.nhtsa.gov/odi/tsbs/2014/MC-10129552-9999.pdf",note:"Software branch limited to listed 2012 Civic body/engine VIN ranges; not a universal large-leak repair"};
const evapOld={label:"Honda Service Bulletin 99-075 — P1456/P1457 troubleshooting",url:"https://static.nhtsa.gov/odi/tsbs/2013/SB-10053545-3978.pdf",note:"Procedure B applies to 1996–2000 Civic and separates fuel-tank-side P1456 from canister-side P1457 testing"};
const evapVent={label:"Honda Service Bulletin 08-016 — 2001–2005 Civic P1457",url:"https://charm.li/Honda/2001/Civic%20LX%20Sedan%20L4-1668cc%201.7L%20SOHC%20MFI/Repair%20and%20Diagnosis/Technical%20Service%20Bulletins/Customer%20Interest/Emissions%20-%20MIL%20ON%2FDTC%20P1457%20Set/",note:"Lists 2001–2005 Civic body styles and 2003–2005 Civic Hybrid ULEV; blocked/restricted fuel-vent-module branch"};
const catalystRequest={label:"Honda 2024 P0420 parts-collection request — selected 2021–2024 Civic 1.5L",url:"https://static.nhtsa.gov/odi/tsbs/2024/MC-11010549-0001.pdf",note:"Expired engineering parts request, not a repair bulletin or warranty promise; exclusions included misfire, mixture and underboost codes"};

const vehicle={name:"Honda Civic",kicker:"HONDA CIVIC · ENGINE, VTEC AND EMISSIONS DIAGNOSTICS",breadcrumb:"Honda Civic",about:"Honda Civic engine and emissions diagnostics",yearsIntro:"Civic diagnostics span D- and B-series distributor engines, the 2002–2005 K20A3 Si, R18 and K-series ninth-generation cars, 2.0L K-series and 1.5L L15 turbo models, Type R/Si calibrations, natural-gas variants and several hybrid systems. Hardware, sensor names, cylinder access, VTEC oil circuits, EVAP logic and fuel pressure differ. Confirm VIN, model year, engine, transmission, body style, emissions label and current Honda campaign status before choosing a test or part."};
type Input=Omit<TroubleCodeGuide,"slug"|"vehicle">&{slug:string};
const article=(x:Input):TroubleCodeGuide=>({...x,slug:`honda/civic/${x.slug}`,vehicle});

export const troubleCodeCivic:TroubleCodeGuide[]=[
article({slug:"p0420",code:"P0420",title:"P0420 Code Honda Civic: Test the Catalyst, Sensors and Root Cause",description:"Diagnose Honda Civic P0420 by checking misfire, fuel control, oil use, exhaust leaks and sensor response before replacing the Bank 1 catalyst.",definition:"Catalyst System Efficiency Below Threshold (Bank 1)",severity:"Service soon",driveAdvice:"A steady MIL with normal power usually allows a short diagnostic trip. Stop sustained driving if the lamp flashes, the engine misfires, raw-fuel odor appears, the converter rattles or power falls sharply; fuel can overheat the catalyst and loose substrate can restrict exhaust.",quickAnswer:"P0420 means the PCM's completed catalyst monitor found less oxygen-storage performance than expected on Bank 1. Every Civic four-cylinder has only one cylinder bank, but converter and sensor packaging varies widely. The code does not prove the downstream sensor or converter failed. Save readiness and freeze data, resolve P030x or mixture faults, document oil/coolant use, inspect for leaks, and graph the upstream A/F sensor against the downstream O2 sensor under Honda's enable conditions. Honda's 2024 request for selected 2021–2024 Civic 1.5L P0420 parts was an expired engineering collection request with exclusions—not a repair instruction, recall or warranty extension.",symptoms:[{key:"normal",label:"MIL on but Civic feels normal",response:"Preserve readiness and test prerequisites before clearing."},{key:"flash",label:"MIL flashes under load",response:"Back off and repair active misfire before catalyst testing."},{key:"rattle",label:"Metallic rattle or weak high-rpm power",response:"Inspect shields and test for damaged or restricted substrate."},{key:"oil",label:"Frequent oil top-ups",response:"Measure consumption; ash can poison a replacement catalyst."}],causes:[{cause:"Aged, contaminated or damaged catalyst",evidence:"All prerequisite systems pass and Honda monitor/evaluation fails",firstTest:"VIN-specific catalyst procedure"},{cause:"Misfire or rich operation overheated catalyst",evidence:"P030x history, flashing MIL, rich correction or fuel-wet plugs",firstTest:"Repair combustion fault first"},{cause:"Oil or coolant contamination",evidence:"Consumption, smoke, fouled plugs or coolant loss",firstTest:"Mechanical/cooling diagnosis"},{cause:"Leak ahead of or near monitored sensors",evidence:"Cold tick, soot, damaged flex joint or leak-test result",firstTest:"Cold exhaust inspection"},{cause:"A/F or O2 sensor/circuit fault",evidence:"Electrical or controlled-response test fails",firstTest:"Graph response and test circuit"}],freezeFrame:["RPM, load, road speed and coolant temperature","All confirmed, pending and permanent codes","Readiness and distance since reset","Fuel correction and misfire history","Upstream A/F and downstream O2 data","Oil/coolant use and exhaust repair history"],steps:[{title:"Keep the monitor evidence",detail:"Record readiness and freeze data before a reset; a recently cleared car has not proved anything."},{title:"Resolve catalyst-damaging faults",detail:"Misfire, excessive fuel, oil burning and coolant entry can ruin a new converter."},{title:"Inspect the exhaust cold",detail:"Check flanges, flex section and sensor bungs for soot or leakage without burn risk."},{title:"Test sensor behavior",detail:"Use the exact generation's A/F and O2 interpretation; generic voltage rules do not fit every Honda sensor."},{title:"Check restriction when symptoms support it",detail:"Rattle or load-related power loss needs temperature/pressure or equivalent approved testing."},{title:"Complete the Honda monitor",detail:"Verify no pending P0420 after prerequisites and enable conditions are satisfied."}],dontReplace:"Do not replace the rear oxygen sensor because its graph resembles the front sensor, and do not fit a converter until the reason it deteriorated is addressed. The 2024 Honda document was a temporary parts request, not evidence that every turbo Civic needs a catalyst.",yearNotes:["Older Civics may combine the manifold and close-coupled catalyst differently from later cars.","2016+ 1.5L turbo cars add direct injection, boost control and oil-dilution history to prerequisite checks.","2021–2024 1.5L cars appeared in an expired Honda parts-collection request only under restrictive conditions.","Hybrid operation changes catalyst temperature and monitor opportunities; use hybrid service mode when specified."],faqs:[{question:"Does P0420 prove the converter is bad?",answer:"No. Misfire, mixture, contamination, leaks and sensor faults must be excluded."},{question:"Can I drive with it?",answer:"Usually briefly with a steady lamp and normal operation; stop for flashing, rattle, odor or power loss."},{question:"Will a rear O2 sensor fix P0420?",answer:"Only if circuit and response testing proves it faulty."},{question:"Does the Honda 2024 notice promise coverage?",answer:"No. It was an expired parts-collection request, not a warranty extension."},{question:"Can oil consumption cause the code?",answer:"Yes. Oil ash can reduce catalyst activity."},{question:"Why did a replacement converter fail again?",answer:"An untreated misfire, mixture, oil/coolant or fitment problem may remain."},{question:"Is Bank 1 left or right?",answer:"A Civic inline-four has one bank; identify the correct monitored converter by model-year diagram."},{question:"What confirms repair?",answer:"Healthy prerequisites and a completed catalyst monitor without pending P0420."}],deepDive:[{heading:"The rear sensor is a monitor, not a verdict",paragraphs:["The PCM judges oxygen storage across defined operating conditions. Similar-looking traces can result from a weak converter, an exhaust leak or invalid upstream control.","A graph captured outside enable conditions is not a substitute for Honda's monitor procedure."]},{heading:"A converter often records someone else's failure",paragraphs:["A flashing misfire or rich injector can send fuel into the substrate. Oil and coolant leave deposits that cleaning cannot reverse.","Review old invoices, permanent codes and consumption instead of judging only today's smooth idle."]},{heading:"The 2024 Honda document has narrow meaning",paragraphs:["Honda sought selected 2021–2024 1.5L parts when several companion faults and prior repairs were absent.","Because the request expired and was not a repair bulletin, it belongs in the evidence history—not in a promised fix."]}],sources:[catalystRequest,serviceExpress,owners]}),

article({slug:"p0171",code:"P0171",title:"P0171 Code Honda Civic: Lean Diagnosis by Engine Generation",description:"Diagnose Civic P0171 using idle-versus-load fuel correction, intake smoke testing, MAP/MAF plausibility and measured fuel delivery.",definition:"Fuel System Too Lean (Bank 1)",severity:"Diagnose promptly",driveAdvice:"Avoid hard acceleration if the Civic hesitates, stalls or shows strongly positive fuel correction. Stop for a flashing MIL, detonation, severe power loss or fuel-pressure warnings. A smooth car with a steady lamp can usually make a short controlled diagnostic trip.",quickAnswer:"P0171 means the PCM reached its correction limit while trying to enrich the only bank on the Civic inline-four. It does not identify an oxygen sensor. Compare short- and long-term correction at hot idle, about 2,500 rpm and controlled load. Correction highest at idle favors a vacuum, PCV, brake-booster or intake-gasket leak. Correction that worsens with load points toward restricted delivery, injector imbalance, incorrect load sensing or—on turbo cars—charge-air/high-pressure fuel problems. Some Civics calculate load primarily from MAP while newer turbo systems expose different airflow and pressure data, so a universal MAF-cleaning prescription is technically unsound.",symptoms:[{key:"idle",label:"Rough or high idle",response:"Compare correction above idle and smoke-test PCV, booster and manifold paths."},{key:"load",label:"Hesitation during acceleration",response:"Graph fuel pressure and calculated load; do not keep loading a fuel-starved engine."},{key:"turbo",label:"1.5T loses boost and runs lean",response:"Pressure-test charge plumbing and compare commanded/actual fuel pressure."},{key:"repair",label:"Code began after intake service",response:"Recheck clamps, seals, hoses and sensor connections before buying parts."}],causes:[{cause:"Unmetered intake, PCV or brake-booster air",evidence:"Correction is most positive at idle and improves with rpm",firstTest:"Regulated smoke test"},{cause:"Load sensor or intake-data error",evidence:"MAP/MAF/IAT values disagree with operating condition",firstTest:"Key-on and running plausibility comparison"},{cause:"Low fuel delivery",evidence:"Correction worsens under load or pressure misses command",firstTest:"Generation-correct pressure/volume test"},{cause:"Injector restriction or imbalance",evidence:"One-cylinder contribution or flow differs",firstTest:"Balance/contribution test"},{cause:"Exhaust leak or biased A/F sensor",evidence:"Cold soot/tick or failed controlled response",firstTest:"Leak inspection then sensor circuit test"}],freezeFrame:["Short- and long-term correction","RPM, load, speed and coolant temperature","MAP/MAF/IAT data provided by that engine","Low- and high-side fuel pressure where supported","Misfire counts and A/F response","Recent intake, injector, turbo or engine work"],steps:[{title:"Save learned correction",detail:"Clearing codes removes the idle-versus-load pattern that localizes the fault."},{title:"Identify the load strategy",detail:"Use the exact engine schematic and PIDs rather than assuming every Civic has the same MAF system."},{title:"Compare three operating points",detail:"Hot idle, raised rpm and safe load distinguish vacuum leakage from delivery limits."},{title:"Smoke-test the full intake path",detail:"Include PCV and brake-booster plumbing plus charge pipes on turbo cars."},{title:"Measure fuel delivery",detail:"Idle pressure alone may miss a weak supply or direct-injection high-side fault."},{title:"Verify correction after repair",detail:"Repeat the original condition and confirm no pending lean code."}],dontReplace:"Do not replace the upstream A/F sensor simply because it reports lean. It may be accurately reporting extra air or too little fuel. Do not spray flammable cleaner around the running engine; a controlled smoke test is safer and more revealing.",yearNotes:["D/B-series, R18, K-series and L15 turbo engines do not share one airflow or fuel-pressure procedure.","All common Civic inline-fours have one bank, so P0171 is not a left-versus-right clue.","Direct-injection turbo cars require both low- and high-pressure evaluation with proper depressurization safety.","Hybrid engine start/stop behavior changes when and how correction should be observed."],faqs:[{question:"Does P0171 mean a bad oxygen sensor?",answer:"No. The sensor often reports a real air/fuel problem."},{question:"Can a vacuum leak cause it?",answer:"Yes, especially when correction is highest at idle."},{question:"Should I clean the MAF?",answer:"Only after confirming that engine uses one and its data supports contamination."},{question:"Can low fuel pressure set P0171?",answer:"Yes, especially when correction worsens with demand."},{question:"Can I drive?",answer:"Limit driving if it hesitates; stop for flashing MIL or serious power loss."},{question:"Can an exhaust leak matter?",answer:"Yes, if it admits oxygen ahead of the A/F sensor."},{question:"Why test hot idle and 2,500 rpm?",answer:"The direction of correction change separates likely leak and delivery patterns."},{question:"What confirms repair?",answer:"Stable correction at idle and load with no pending P0171."}],deepDive:[{heading:"Fuel correction is a pattern, not a magic number",paragraphs:["A snapshot cannot show whether the PCM is compensating mainly at idle or throughout the load range.","Graph correction with rpm and load; reproduce the freeze-frame condition without unsafe acceleration."]},{heading:"Turbo Civics have two pressure stories",paragraphs:["A leak between compressor and throttle can appear primarily under boost, while crankcase or manifold leakage dominates vacuum operation.","Direct injection also adds high-side pressure. Never loosen a running high-pressure connection as a test."]},{heading:"Sensor names changed across generations",paragraphs:["Older speed-density systems and newer airflow-equipped calibrations require different plausibility checks.","The useful question is whether all load signals agree, not whether one generic grams-per-second rule is met."]}],sources:[serviceExpress,owners]}),

article({slug:"p0300",code:"P0300",title:"P0300 Code Honda Civic: Random Misfire Diagnosis Without Guessing",description:"Diagnose Civic P0300 with cylinder counters, plugs, coils, injectors and compression, including the exact 2016–2018 1.5L Honda bulletin branch.",definition:"Random/Multiple Cylinder Misfire Detected",severity:"Stop soon",driveAdvice:"A flashing MIL means active catalyst-damaging misfire. Release the throttle and stop as soon as safe. A steady lamp with smooth operation may allow a short move for diagnosis, but stop for strong shaking, raw-fuel odor, overheating, low oil pressure or mechanical noise.",quickAnswer:"P0300 means crankshaft-speed variation showed misfire across multiple cylinders or without one cylinder consistently dominating. Save P0301–P0304 companions, enhanced cylinder counts, freeze data and fuel correction before clearing. If one counter dominates, test that cylinder; if all rise, test shared fuel, air, timing and voltage causes. Honda bulletin 19-038 is a special branch only for VIN-eligible 2016–2018 Civic 1.5L vehicles with specified misfire codes/P0172 or whirling noise. It instructs technicians to handle bulletin 18-137 first when applicable and may lead to plug inspection and camshaft/rocker inspection. It is not permission to replace those parts on other engines or years.",symptoms:[{key:"flash",label:"MIL flashes and engine shakes",response:"Stop loading the engine to protect the catalyst."},{key:"cold",label:"Misfire only after cold soak",response:"Capture counters immediately; inspect fuel leakage, ignition and sealing while cold."},{key:"load",label:"Breaks up under boost/load",response:"Test plug condition, ignition reserve and commanded/actual fuel pressures."},{key:"whirl",label:"2016–2018 1.5L with whirling noise",response:"Check VIN/status and bulletin 18-137/19-038 applicability with Honda."}],causes:[{cause:"Worn, fouled or damaged plugs/coils",evidence:"Counts rise under load and a controlled swap follows",firstTest:"Labelled plug inspection and one coil swap"},{cause:"Injector or fuel-pressure problem",evidence:"Cold/load pattern, pressure mismatch or contribution difference",firstTest:"Pressure and injector tests"},{cause:"Vacuum/charge leak or purge fault",evidence:"Fuel correction pattern and smoke/bidirectional evidence",firstTest:"Smoke and purge sealing tests"},{cause:"Compression, valve-clearance or timing fault",evidence:"Misfire stays with low relative compression",firstTest:"Compression then leak-down/timing check"},{cause:"19-038 covered 1.5L condition",evidence:"2016–2018 1.5L VIN/status and required diagnosis match",firstTest:"Honda bulletin workflow"}],freezeFrame:["All-cylinder misfire counts","P0301–P0304/P0172 companion codes","RPM, load, coolant temperature and speed","Fuel correction and pressure data","Plug deposits kept in cylinder order","VIN, 1.5L status and prior 18-137 repair"],steps:[{title:"Preserve the event",detail:"Record freeze data and counters before clearing or moving coils."},{title:"Separate one-cylinder from shared",detail:"A dominant cylinder needs a targeted path; equal random counts need common causes."},{title:"Inspect plugs in order",detail:"Deposits, cracks, gap and wetness are evidence; photograph them before replacement."},{title:"Use one controlled coil swap",detail:"If the counter moves, ignition evidence is strong; if it stays, continue to fuel/mechanical tests."},{title:"Measure fuel and sealing",detail:"Test injector delivery, pressure, relative compression and leak-down as indicated."},{title:"Apply 19-038 only when matched",detail:"Check VIN and current program status; do not generalize its remedy."},{title:"Verify cold and loaded",detail:"Repeat the original condition without a flashing-MIL road test."}],dontReplace:"Do not install four coils because P0300 says multiple. Do not assume the 1.5L bulletin still provides coverage or applies outside 2016–2018; eligibility, exclusions and required inspection matter. A mechanical fault can briefly improve with new plugs and then return.",yearNotes:["2016–2018 1.5L: bulletin 19-038 lists P0300–P0304/P0172 and whirling-noise branches; check VIN and 18-137 status first.","Naturally aspirated 2.0L, older R18/K engines and later Civics are outside that bulletin remedy.","Direct-injection systems require safe pressure handling and model-specific injector tests.","A flashing MIL is a driving-risk signal regardless of generation."],faqs:[{question:"Is P0300 a bad coil?",answer:"Not necessarily; it names no cylinder or component."},{question:"Can I drive?",answer:"Not with a flashing lamp or strong shaking."},{question:"Does 19-038 cover every turbo Civic?",answer:"No. It lists 2016–2018 1.5L vehicles and requires VIN/status checks."},{question:"Should I replace all plugs first?",answer:"Inspect and record them first; replacement without cause analysis can hide evidence."},{question:"Can injectors cause random misfire?",answer:"Yes, through leakage, restriction or pressure faults."},{question:"Can valve clearance matter?",answer:"Yes, especially when sealing changes with temperature."},{question:"Why save permanent codes?",answer:"They preserve emissions history even after clearing and may explain catalyst risk."},{question:"What confirms repair?",answer:"Stable counters through the original cold/load condition with no pending misfire."}],deepDive:[{heading:"Cylinder counters turn random into a direction",paragraphs:["P0300 is broad, but enhanced counts may show one cylinder leading under a repeatable condition.","Capture cold-start data before heat expansion and fuel corrections make the symptom disappear."]},{heading:"The 1.5L bulletin is conditional",paragraphs:["Honda specifies VIN eligibility and tells technicians to complete applicable 18-137 work before the 19-038 branch.","Its inspection can involve plugs and camshaft/rocker assemblies; that sequence is not a universal DIY parts list."]},{heading:"The plug is a combustion witness",paragraphs:["Fuel wetness, oil deposits, coolant-cleaning, cracked porcelain and excess gap point to different next tests.","Keep plugs labelled. A pile of mixed plugs loses cylinder-specific evidence."]}],sources:[misfireBulletin,serviceExpress,owners]}),

article({slug:"p2646",code:"P2646",title:"P2646 Code Honda Civic: Rocker-Arm Oil Pressure System Diagnosis",description:"Diagnose Civic P2646 with oil condition, spool-valve screening and circuit tests, including Honda bulletin 13-021's exact Civic coverage.",definition:"Rocker Arm Oil Pressure Switch Circuit Low Voltage",severity:"Diagnose promptly",driveAdvice:"Avoid high rpm and hard acceleration because the PCM may limit engine speed when VTEC oil-pressure confirmation fails. Stop for an oil-pressure warning, loud valvetrain noise, very low oil, overheating or mechanical knock; those are lubrication risks, not merely a VTEC code.",quickAnswer:"P2646 means the PCM saw the rocker-arm oil-pressure-switch signal remain in the low-voltage state when the monitored VTEC/VTC operating state required otherwise. It does not prove low engine oil pressure or a bad spool-valve assembly. Check oil level, grade, contamination and maintenance first, then identify the exact switch, connector, screen and oil passage from the Civic engine diagram. Honda bulletin 13-021 names an intermittent switch branch for 2002–2005 Civic Si and 2012–2013 Civic except Si and Hybrid. It directs switch/O-ring replacement in the matched branch and normal troubleshooting if the code returns. Other Civic years/engines do not inherit that shortcut.",symptoms:[{key:"limit",label:"Engine will not rev normally",response:"Avoid forcing it through fail-safe; diagnose the VTEC confirmation fault."},{key:"oil",label:"Oil low or warning lamp appears",response:"Shut down and verify lubrication safely before circuit testing."},{key:"intermittent",label:"Code intermittent on a covered Civic",response:"Verify exact 13-021 applicability and inspect connector/oil condition."},{key:"returns",label:"P2646 returns after switch replacement",response:"Follow normal oil-pressure, spool-valve, passage and circuit diagnosis."}],causes:[{cause:"Low, wrong or badly degraded engine oil",evidence:"Level/condition/history abnormal",firstTest:"Correct level/spec and investigate consumption/leaks"},{cause:"Intermittent rocker-arm oil-pressure switch",evidence:"Exact 13-021 model/year branch and circuit evidence",firstTest:"Bulletin applicability and switch test"},{cause:"Blocked spool-valve screen or oil passage",evidence:"Contamination or pressure fails under command",firstTest:"Inspect screen and measure specified pressure"},{cause:"Connector/wiring short or open",evidence:"Wiggle/voltage/continuity test fails",firstTest:"Loaded circuit test"},{cause:"Spool valve or mechanical oil-control fault",evidence:"Command present but hydraulic state incorrect",firstTest:"Honda actuation and oil-pressure procedure"}],freezeFrame:["Oil level, grade and change interval","RPM, load and coolant temperature","VTEC command and switch status","Battery/charging voltage","P2647/P2651/P2652 or oil-pressure companions","Exact engine, VIN and 13-021 applicability"],steps:[{title:"Protect the engine first",detail:"Treat low oil or an oil-pressure warning as a lubrication issue and stop running it."},{title:"Verify the exact Civic branch",detail:"13-021 covers 2002–2005 Si and 2012–2013 except Si/Hybrid—not every Civic."},{title:"Inspect oil and external evidence",detail:"Correct grade/level and look for sludge, leakage, consumption and connector contamination."},{title:"Test the switch circuit",detail:"Compare actual voltage/state with command using the engine-specific schematic."},{title:"Check screen, passage and pressure",detail:"A new electrical switch cannot repair restricted hydraulic flow."},{title:"Reproduce safely",detail:"Verify correct status transition without forcing a low-oil-pressure engine to high rpm."}],dontReplace:"Do not replace the complete spool-valve assembly from the code alone. Bulletin 13-021 identifies a switch/O-ring branch only for listed Civics, and explicitly returns persistent codes to normal troubleshooting. Never use thicker oil to hide a pressure problem.",yearNotes:["2002–2005 Civic Si is listed in bulletin 13-021; ordinary 1.7L Civics are not listed in that branch.","2012–2013 Civic except Si and Hybrid is listed; the exclusions matter.","Later turbo, Type R and 2.0L engines use different oil-control layouts and procedures.","P2646 is the low-state code; interpret it with command state rather than as a generic low-oil-pressure message."],faqs:[{question:"Does P2646 mean the engine is low on oil?",answer:"Not necessarily, but oil level and condition are the first safety checks."},{question:"Does bulletin 13-021 cover every Civic?",answer:"No. It lists 2002–2005 Si and 2012–2013 except Si/Hybrid."},{question:"Can I keep driving?",answer:"Limit rpm; stop for an oil-pressure warning or valvetrain noise."},{question:"Is the spool-valve assembly always bad?",answer:"No. Oil, switch, wiring, screen and pressure can each cause the result."},{question:"Why did a new switch not fix it?",answer:"Restriction, wiring or true hydraulic pressure may be the root cause."},{question:"Can dirty oil set P2646?",answer:"Contamination can restrict the fine oil-control screen/passages."},{question:"Should I rev it to test VTEC?",answer:"Only under the approved procedure after lubrication safety is established."},{question:"What confirms repair?",answer:"Correct commanded switch transition and no pending P2646 under enable conditions."}],deepDive:[{heading:"Electrical wording describes a monitored state",paragraphs:["The PCM watches whether the pressure switch agrees with the commanded rocker-arm oil state.","A low-voltage description does not distinguish a grounded circuit from hydraulic pressure holding the switch in that state."]},{heading:"The bulletin saves guessing only when applicability matches",paragraphs:["Honda names two Civic populations and an intermittent switch failure. Trim and hybrid exclusions are explicit.","If the code returns after the bulletin repair, Honda directs normal troubleshooting rather than repeated switch replacement."]},{heading:"Oil quality is part of the hydraulic circuit",paragraphs:["VTEC oil passages and screens are small. Low level, wrong viscosity and sludge change response time.","Correct the reason for low or contaminated oil; a top-up alone may not be a durable repair."]}],sources:[rockerBulletin,serviceExpress,owners]}),

article({slug:"p2647",code:"P2647",title:"P2647 Code Honda Civic: Rocker-Arm Pressure Switch Stuck High",description:"Diagnose Civic P2647 by separating a high switch state from wiring, trapped pressure, spool-valve restriction and the limited 13-021 bulletin branch.",definition:"Rocker Arm Oil Pressure Switch Circuit High Voltage",severity:"Diagnose promptly",driveAdvice:"Keep rpm and load low because fail-safe may restrict performance. Stop immediately for the oil-pressure lamp, knocking, severe valvetrain noise or very low oil. P2647 is a monitored VTEC oil-control fault; it is not permission to ignore a separate lubrication warning.",quickAnswer:"P2647 is the opposite monitored state from P2646: the rocker-arm oil-pressure-switch circuit remains high when the PCM expects the other state. Causes include an open circuit or connector problem, a switch stuck internally, trapped hydraulic pressure, restricted return/strainer flow or a spool valve that does not release. Honda bulletin 13-021 includes P2647/P2652 for 2002–2005 Civic Si and 2012–2013 Civic except Si/Hybrid, identifying an intermittent switch branch. Confirm exact applicability, oil and circuit behavior. If the code returns after that repair, the bulletin says to continue standard troubleshooting.",symptoms:[{key:"limit",label:"Reduced rpm/performance",response:"Do not repeatedly trigger VTEC; capture command and switch status."},{key:"oil",label:"Oil lamp or mechanical noise",response:"Stop and test lubrication before electrical diagnosis."},{key:"covered",label:"Intermittent code on listed year/trim",response:"Check 13-021 VIN/model applicability and switch connector."},{key:"hot",label:"Code appears only hot",response:"Graph oil temperature context, command/state and pressure rather than guessing viscosity."}],causes:[{cause:"Open/high-resistance switch circuit",evidence:"State remains high and loaded circuit test fails",firstTest:"Connector, terminal and circuit voltage-drop test"},{cause:"Intermittent pressure switch",evidence:"Exact bulletin population plus required evidence",firstTest:"13-021 switch procedure"},{cause:"Spool valve fails to release",evidence:"Command changes but hydraulic state stays pressurized",firstTest:"Actuation and oil-pressure test"},{cause:"Restricted screen/return passage",evidence:"Contamination and delayed state transition",firstTest:"Inspect serviceable screen/passages"},{cause:"Wrong, degraded or contaminated oil",evidence:"Level/viscosity/service history abnormal",firstTest:"Correct oil condition and find source"}],freezeFrame:["Rocker-arm command and switch state","RPM, load, ECT and oil-temperature context","Battery voltage","Oil level/specification/service history","Companion P2646/P2651/P2652 codes","Engine, trim, model year and bulletin match"],steps:[{title:"Separate code from oil warning",detail:"A red oil-pressure warning or noise requires shutdown regardless of P2647 diagnosis."},{title:"Confirm bulletin population",detail:"Check Si/Hybrid exclusions and exact year before using 13-021."},{title:"Graph command versus feedback",detail:"Determine whether the high state is constant, delayed or heat/vibration dependent."},{title:"Load-test wiring",detail:"A continuity beep can miss terminal drag or a circuit that opens under vibration."},{title:"Evaluate hydraulic release",detail:"Inspect oil, screen and passages and measure pressure as Honda specifies."},{title:"Verify both state transitions",detail:"A durable repair must pass command-on and command-off behavior without a pending code."}],dontReplace:"Do not treat P2647 as the same repair as P2646 merely because both mention the rocker-arm switch. State direction helps separate open/high circuits and trapped pressure from low-state faults. Do not apply bulletin 13-021 beyond its listed Civic populations.",yearNotes:["2002–2005 Civic Si and 2012–2013 Civic except Si/Hybrid are the Civic groups in 13-021.","A regular 2002–2005 1.7L Civic is not covered by that bulletin branch.","P2647/P2652 are high-state variants; P2646/P2651 are low-state variants in the bulletin.","Later K/L-series oil-control hardware requires the VIN-correct schematic and thresholds."],faqs:[{question:"What is the difference between P2646 and P2647?",answer:"They report opposite monitored switch-circuit states; diagnosis must account for command state."},{question:"Is P2647 always a switch?",answer:"No. Wiring, spool-valve release, restriction and oil condition can mimic it."},{question:"Can I drive?",answer:"Keep it limited; stop for an oil warning or mechanical noise."},{question:"Does 13-021 include Civic Si?",answer:"It includes 2002–2005 Si, but excludes 2012–2013 Si."},{question:"Does it include Civic Hybrid?",answer:"The 2012–2013 Hybrid is excluded from the Civic branch."},{question:"Why load-test wiring?",answer:"A weak terminal can pass resistance checks unloaded and fail during operation."},{question:"Can wrong oil matter?",answer:"Yes. Hydraulic response depends on correct level, viscosity and cleanliness."},{question:"What confirms repair?",answer:"Correct command-to-feedback transitions and no pending P2647."}],deepDive:[{heading:"High state can be electrical or hydraulic",paragraphs:["An open signal circuit may be interpreted high, while trapped oil pressure can keep a healthy switch in the same state.","Graph the PCM command alongside feedback before deciding which side to test."]},{heading:"The two Civic bulletin groups are not identical",paragraphs:["Honda includes early K20A3 Si cars but excludes the 2012–2013 Si and Hybrid from the later group.","A keyword match without year and trim verification can therefore recommend the wrong repair."]},{heading:"Return flow matters",paragraphs:["VTEC diagnostics are not only about building pressure. Oil also must release and the switch must report that change.","Sludge, a damaged valve or restricted passage can delay the off transition and mature P2647."]}],sources:[rockerBulletin,serviceExpress,owners]}),

article({slug:"p1457",code:"P1457",title:"P1457 Code Honda Civic: Canister-Side EVAP Leak Diagnosis",description:"Diagnose Civic P1457 with Honda's canister-side vacuum tests and separate 1996–2000 and 2001–2005 bulletin branches.",definition:"EVAP Control System Leakage (EVAP Canister System)",severity:"Service soon",driveAdvice:"P1457 usually permits short driving when the Civic runs normally and no fuel odor or wetness exists. Park outdoors and stop for liquid fuel, a strong vapor smell, damaged tank plumbing or refueling problems. Keep sparks and flames away; use only approved low-pressure EVAP equipment.",quickAnswer:"Honda P1457 identifies the canister side of the older EVAP system; P1456 identifies the fuel-tank side. That distinction matters: a gas cap is not the automatic answer. Inspect canister hoses, bypass/vent and purge valves, then use Honda's vacuum/pressure sequence or a regulated smoke test. Bulletin 99-075 provides Procedure B for 1996–2000 Civic. Bulletin 08-016 covers listed 2001–2005 Civic body styles and 2003–2005 Civic Hybrid ULEV, identifying a blocked or restricted EVAP solenoid valve/fuel vent module branch. Test applicability and valve sealing rather than replacing the entire canister.",symptoms:[{key:"odor",label:"Fuel odor or visible wetness",response:"Stop and inspect safely before energizing valves."},{key:"old",label:"1996–2000 Civic",response:"Use Procedure B in 99-075 and keep P1456 tank-side logic separate."},{key:"new",label:"2001–2005 Civic",response:"Check 08-016 coverage and test the fuel vent module restriction branch."},{key:"returns",label:"Code returns after a gas cap",response:"Focus on the canister-side valves, hoses and purge sealing."}],causes:[{cause:"Restricted fuel vent module/EVAP solenoid",evidence:"Matched 08-016 application and failed flow/vacuum test",firstTest:"Bulletin diagnostic sequence"},{cause:"Corroded or leaking bypass/vent valve",evidence:"Valve will not seal/hold vacuum or has water corrosion",firstTest:"Individual valve vacuum test"},{cause:"Cracked/disconnected canister-side hose",evidence:"Visual or regulated smoke evidence",firstTest:"Hose routing inspection and sectional smoke test"},{cause:"Purge valve leakage",evidence:"Vacuum passes when valve should be closed",firstTest:"Closed-state sealing test"},{cause:"Canister or two-way valve leak/restriction",evidence:"System fails after hoses/solenoids pass",firstTest:"Honda sectional vacuum procedure"}],freezeFrame:["Exact model year, engine and body style","P1456/P044x and circuit companion codes","Fuel level and soak/ambient conditions","Tank-pressure data if equipped","Recent rear-body, tank or canister work","Valve command, vacuum-hold and smoke-test results"],steps:[{title:"Identify the EVAP generation",detail:"1996–2000 and 2001–2005 Civic branches use different component layouts."},{title:"Confirm canister-side code meaning",detail:"Do not substitute P1456 fuel-tank-side troubleshooting."},{title:"Inspect routing and contamination",detail:"Look for split hoses, incorrect connections, water intrusion and damaged canister fittings."},{title:"Test each valve mechanically",detail:"A clicking solenoid may still leak or be flow-restricted."},{title:"Use regulated smoke or Honda vacuum tests",detail:"Section the system and avoid unregulated shop air."},{title:"Run the service-bay monitor",detail:"Meet temperature/fuel conditions and confirm no pending P1457."}],dontReplace:"Do not call P1457 a loose-cap code on these Civics. The cap is primarily on the tank side, while P1457 points diagnostic attention to the canister side. Do not condemn a charcoal canister until valves and hose routing have been isolated.",yearNotes:["1996–2000 Civic: bulletin 99-075 Procedure B gives updated P1457 troubleshooting.","2001–2005 2/4-door, 2002–2005 3-door and 2003–2005 Hybrid ULEV are listed in 08-016.","08-016 identifies a blocked/restricted fuel vent module branch, not every possible P1457 cause.","Newer Civics generally use generic P044x leak codes; do not force old P1457 component names onto them."],faqs:[{question:"Is P1457 a gas-cap code?",answer:"Not primarily; Honda defines it as the canister-side EVAP leak."},{question:"What is P1456?",answer:"On these systems it is the fuel-tank-side leak code."},{question:"Can I drive?",answer:"Usually briefly without odor or liquid leakage."},{question:"Does 08-016 cover a 1999 Civic?",answer:"No. Use the 1996–2000 procedure in 99-075."},{question:"Does a valve click prove it is good?",answer:"No. It may click yet leak or remain restricted."},{question:"Can smoke testing find it?",answer:"Yes when pressure is EVAP-safe and the system is sectioned correctly."},{question:"Should I replace the canister?",answer:"Only after valves, hoses and canister integrity are tested."},{question:"What confirms repair?",answer:"Correct vacuum/valve behavior and a completed EVAP test without pending P1457."}],deepDive:[{heading:"Honda split the leak into two regions",paragraphs:["P1456 and P1457 were designed to guide technicians toward different sides of the older system.","Treating both as cap faults discards the most useful diagnostic information in the code."]},{heading:"Restriction can look like leakage",paragraphs:["The self-test expects valves and passages to move vapor and hold vacuum in sequence.","A restricted fuel vent module can prevent the expected pressure change even when no hose has a visible hole."]},{heading:"Mechanical testing beats a click test",paragraphs:["Solenoid sound confirms movement at best; it does not prove flow or sealing.","Apply the specified vacuum and command while observing whether the valve holds, releases and flows correctly."]}],sources:[evapOld,evapVent,serviceExpress]}),

article({slug:"p0135",code:"P0135",title:"P0135 Code Honda Civic: Upstream A/F Sensor Heater Diagnosis",description:"Diagnose Civic P0135 by testing the Bank 1 Sensor 1 heater feed, PCM control, resistance and harness before replacing the upstream sensor.",definition:"Oxygen Sensor Heater Circuit Malfunction (Bank 1, Sensor 1)",severity:"Service soon",driveAdvice:"A heater-code Civic usually remains driveable for a short period, but cold-start emissions and fuel control may suffer. Stop for a flashing MIL, severe misfire, melted wiring, blown fuses that recur, or exhaust damage. Let the exhaust cool before connector work.",quickAnswer:"P0135 means the PCM did not see expected electrical behavior from the heater in Bank 1 Sensor 1—the upstream sensor before the catalyst. Honda may call that component the primary heated oxygen sensor or air/fuel ratio sensor depending on generation; those are not interchangeable universal parts. With the correct wiring diagram, verify battery supply, fuse/shared feed, connector tension, heater resistance/current and PCM-controlled ground. A resistance value copied from another Civic engine can condemn a good wide-range sensor. If several heater codes set together, start at the shared power source rather than ordering multiple sensors.",symptoms:[{key:"cold",label:"MIL returns soon after cold start",response:"Record time-to-fault and heater current/voltage before the exhaust warms."},{key:"fuse",label:"Heater fuse opens again",response:"Disconnect affected loads and locate the short; do not fit a larger fuse."},{key:"multiple",label:"Several heater codes stored",response:"Trace the shared feed, relay/fuse and grounds first."},{key:"repair",label:"Code began after exhaust work",response:"Inspect harness routing, pin fit and sensor connector identification."}],causes:[{cause:"Open heater element in upstream sensor",evidence:"VIN-correct resistance/current test fails at sensor",firstTest:"Cold resistance and current test"},{cause:"Missing fused battery feed",evidence:"No loaded voltage at heater supply",firstTest:"Fuse/relay/feed voltage-drop test"},{cause:"Open/shorted PCM control wire",evidence:"Command present but circuit cannot carry/control current",firstTest:"Loaded control-circuit test"},{cause:"Loose, corroded or heat-damaged connector",evidence:"Poor terminal drag or heat/vibration dropout",firstTest:"Terminal inspection and wiggle test"},{cause:"Wrong sensor or crossed connector",evidence:"Part/routing changed after repair",firstTest:"VIN part and connector verification"}],freezeFrame:["Battery voltage and coolant temperature","Time since start and heater command","Heater current/duty data if supported","All related heater and voltage codes","Fuse condition and exhaust repair history","Exact engine, sensor part and wiring diagram"],steps:[{title:"Identify Sensor 1",detail:"It is upstream of the monitored catalyst, but location and Honda naming vary."},{title:"Check the whole code list",detail:"Multiple heaters or voltage codes make a shared supply fault more likely."},{title:"Inspect the cold harness",detail:"Look for melted insulation, stretched wiring, oil/water and swapped connectors."},{title:"Verify loaded power",detail:"Open-circuit battery voltage can disappear when the heater draws current."},{title:"Test heater and control",detail:"Use model-specific resistance/current and PCM control-pin instructions."},{title:"Verify a cold start",detail:"Confirm commanded current and no pending P0135 from a true cold soak."}],dontReplace:"Do not buy an upstream sensor before checking power and control, and do not use a downstream sensor because the connector fits. Never upsize a fuse or pierce insulation where corrosion will follow. Exhaust components can remain hot long after shutdown.",yearNotes:["Older narrow-band heated oxygen sensors and later wide-range A/F sensors use different signal and heater behavior.","Civic has one bank, but Sensor 1 versus Sensor 2 still matters.","Harness routing near the manifold, catalyst and shields changes by D/R/K/L-series engine.","A replacement must match VIN, emissions calibration and connector—not merely thread size."],faqs:[{question:"Which sensor is Bank 1 Sensor 1?",answer:"The upstream/pre-catalyst feedback sensor on the Civic's only bank."},{question:"Does P0135 mean the sensing element is bad?",answer:"It specifically flags the heater circuit; power, control and wiring can be responsible."},{question:"Can I drive?",answer:"Usually briefly if operation is normal and wiring is not overheating."},{question:"Can a fuse cause P0135?",answer:"Yes, but find why it opened before replacement."},{question:"Can I test resistance?",answer:"Yes, using the exact Honda specification and correct heater pins."},{question:"Why are two heater codes present?",answer:"They may share a fuse, relay or supply circuit."},{question:"Will a universal sensor work?",answer:"It risks wrong heater and signal characteristics; use VIN-correct specification."},{question:"What confirms repair?",answer:"Normal cold-start heater current/control and no pending P0135."}],deepDive:[{heading:"Sensor terminology matters",paragraphs:["Honda service information may call the upstream unit an A/F sensor while a generic scanner labels it oxygen sensor 1.","Identify it by function, location, connector and wiring diagram before testing pins."]},{heading:"Voltage must be checked under load",paragraphs:["A corroded terminal can show battery voltage on a high-impedance meter but collapse when heater current flows.","Voltage drop and current reveal circuit capacity better than an unloaded continuity beep."]},{heading:"A repeated fuse is evidence",paragraphs:["A fuse that opens again points toward a shorted heater, chafed harness or another load on the shared branch.","Increasing fuse size can turn diagnostic evidence into harness damage or fire."]}],sources:[serviceExpress,owners]}),

article({slug:"p0455",code:"P0455",title:"P0455 Code Honda Civic: Large EVAP Leak and 2012 VIN Check",description:"Diagnose Civic P0455 using cap evidence, purge/vent commands, tank-pressure data and safe smoke testing, with Honda bulletin 14-010 limits.",definition:"EVAP System Large Leak Detected",severity:"Service soon",driveAdvice:"A Civic with only P0455 and normal operation can usually be driven briefly. Park outdoors and stop for strong gasoline odor, visible wetness, tank damage or refueling spit-back. Keep ignition sources away and never pressurize the EVAP system with uncontrolled shop air.",quickAnswer:"P0455 means the EVAP monitor could not create or hold the expected vacuum/pressure; it does not locate the opening. Record the cap's found condition, fuel level, tank-pressure data and recent fuel-pump or collision work. Then test whether purge and vent valves actually seal and use approved low-pressure smoke to section the system. Honda bulletin 14-010 provides a PGM-FI software branch only for five listed 2012 Civic engine/body VIN ranges: 1.8L coupe, Si coupe, two 1.8L sedan production groups and Si sedan. Exact VIN and calibration must match. A 2013 or later Civic does not qualify from the code alone.",symptoms:[{key:"fill",label:"MIL followed refueling",response:"Photograph cap position and inspect seal/filler surface before tightening."},{key:"2012",label:"Affected 2012 body/engine",response:"Check the complete VIN range and current calibration against 14-010."},{key:"start",label:"Hard start after refueling",response:"Test purge-valve closed-state leakage into the intake."},{key:"odor",label:"Strong vapor odor",response:"Stop and check safely for liquid leakage before electrical tests."}],causes:[{cause:"Loose, missing, damaged or wrong cap",evidence:"Found condition or cap/filler sealing test fails",firstTest:"Cap and filler-neck inspection"},{cause:"Purge valve stuck open",evidence:"Vacuum passes with purge commanded closed",firstTest:"Closed-state sealing test"},{cause:"Vent valve open or hose disconnected",evidence:"System cannot seal and smoke exits",firstTest:"Command valve and smoke test"},{cause:"Canister, tank or pump-module seal leak",evidence:"Localized smoke/pressure decay",firstTest:"Sectional EVAP test"},{cause:"Software branch in exact 2012 VIN range",evidence:"14-010 applicability and calibration match",firstTest:"Honda VIN/program check"}],freezeFrame:["Fuel level, ambient and soak temperature","Fuel-tank pressure sensor value","Purge/vent commands","P0456/P0441 or circuit companion codes","Cap found condition and recent refueling","Exact 2012 VIN and current calibration"],steps:[{title:"Preserve refueling evidence",detail:"Do not automatically tighten the cap before recording what was found."},{title:"Check 14-010 precisely",detail:"Match year, engine, body style, VIN range and software—not just P0455."},{title:"Test valve sealing",detail:"A click does not prove purge or vent closes against flow."},{title:"Use regulated smoke",detail:"Inspect filler, hoses, canister and top-of-tank seals at EVAP-safe pressure."},{title:"Validate pressure sensing",detail:"A biased tank-pressure signal can make a sealed system fail the monitor."},{title:"Complete monitor conditions",detail:"After repair, satisfy fuel-level/soak requirements and check pending codes."}],dontReplace:"Do not replace the cap, purge valve and canister as a package. Each can be isolated. Do not claim bulletin 14-010 applies to every 2012 Civic without comparing the full VIN range, and do not apply its software fix to other years.",yearNotes:["14-010 lists specific 2012 1.8L and Si coupe/sedan VIN ranges; applicability is not model-name-only.","Older Civics using P1456/P1457 have different regional leak logic and component names.","Later capless or revised EVAP layouts require the exact year schematic.","Fuel level and soak conditions can delay monitor completion after a correct repair."],faqs:[{question:"Is P0455 always the gas cap?",answer:"No. Purge, vent, hoses, canister, tank seals and sensing can cause it."},{question:"Does 14-010 cover every 2012 Civic?",answer:"No. It publishes engine/body-specific VIN ranges."},{question:"Can I drive?",answer:"Usually briefly without odor or liquid fuel; stop if either appears."},{question:"Can a purge valve cause hard starting?",answer:"Yes, if it leaks vapor into the intake after refueling."},{question:"Can I use shop air?",answer:"Not unregulated; EVAP systems require approved low pressure."},{question:"Why did a new cap fail to fix it?",answer:"Another seal/valve may be open, or the filler surface may be damaged."},{question:"Why is readiness incomplete?",answer:"EVAP monitors require specific fuel level, soak and temperature conditions."},{question:"What confirms repair?",answer:"Correct valve/pressure behavior and a completed monitor without pending P0455."}],deepDive:[{heading:"The cap's found state disappears quickly",paragraphs:["A loose or cross-threaded cap is valuable evidence only until someone tightens it.","Record the seal and filler surface as well; a good cap cannot seal a damaged neck."]},{heading:"A normal vent path can imitate a hole",paragraphs:["If a commanded valve does not close mechanically, test pressure escapes through an intended passage.","Verify actual sealing rather than concluding that the tank has a large crack."]},{heading:"Software applicability is a full-VIN question",paragraphs:["Honda lists five distinct 2012 Civic production groups in 14-010.","A matching year and code are insufficient; technicians must confirm VIN and calibration before programming."]}],sources:[evapSoftware,serviceExpress,owners]}),

article({slug:"p0128",code:"P0128",title:"P0128 Code Honda Civic: Thermostat and Cold-Start Data Test",description:"Diagnose Civic P0128 with cold-soak ECT/IAT comparison, a graphed warm-up curve, fan checks and correct thermostat verification.",definition:"Coolant Thermostat (Coolant Temperature Below Thermostat Regulating Temperature)",severity:"Service soon",driveAdvice:"P0128 generally describes slow warm-up, but stop for overheating, steam, coolant loss, an actual temperature warning or cabin heat that suddenly goes cold. If coolant is full when checked cold and temperature remains stable, a short data-recording drive is normally reasonable.",quickAnswer:"P0128 means coolant temperature remained below the PCM's modeled regulating range after enough operating time and load. A thermostat stuck open is common, but begin after an overnight soak: ECT and intake-air temperature should be reasonably close to each other and ambient before start. Graph ECT, time, speed, load, fan command and cabin-heat behavior. A cold-biased ECT sensor, low coolant, trapped air, fans running without request or the wrong thermostat can produce the same monitor result. Civic cooling capacity and hybrid engine-off behavior vary by engine, so use Honda's VIN-specific procedure and part specification.",symptoms:[{key:"heat",label:"Cabin heat is slow",response:"Check coolant cold and record the entire warm-up curve."},{key:"road",label:"ECT drops at highway speed",response:"A thermostat leaking open becomes likely; confirm with scan data."},{key:"gauge",label:"Dash gauge appears normal",response:"Use scan ECT; the display is damped and not a precision instrument."},{key:"hot",label:"Temperature rises or coolant escapes",response:"Abort P0128 testing and diagnose overheating/leakage first."}],causes:[{cause:"Thermostat stuck open or incorrect",evidence:"Slow rise and temperature falls with road airflow",firstTest:"Cold-start warm-up graph"},{cause:"ECT sensor/circuit biased cold",evidence:"Cold-soak ECT differs materially from IAT/ambient",firstTest:"Sensor/circuit plausibility test"},{cause:"Low coolant or trapped air",evidence:"Low reservoir/radiator when cold, recent service or unstable heat",firstTest:"Leak test and correct bleeding"},{cause:"Radiator fans operating unnecessarily",evidence:"Fans run cold with A/C off and no PCM request",firstTest:"Compare command and actual operation"},{cause:"Wrong load/temperature input",evidence:"Companion codes or implausible freeze data",firstTest:"Resolve prerequisite input faults"}],freezeFrame:["ECT, IAT and measured ambient before start","Time, rpm, load and speed","Fan command and A/C request","Coolant level and recent service","Cabin heat and outside temperature","Companion temperature/voltage/load codes"],steps:[{title:"Start truly cold",detail:"Compare ECT and IAT before starting; thermostat position cannot create a pre-start sensor mismatch."},{title:"Inspect coolant safely",detail:"Check level/leaks cold and never open a pressurized hot system."},{title:"Graph warm-up",detail:"Capture rise rate, regulation and any drop as road airflow increases."},{title:"Observe fans",detail:"Separate commanded A/C or thermal operation from a relay/control fault."},{title:"Verify part and bleeding",detail:"Thermostat specification, orientation and air-bleeding procedure depend on engine."},{title:"Repeat comparable conditions",detail:"Confirm stable regulation and no pending P0128."}],dontReplace:"Do not replace the thermostat before the cold-soak comparison, and do not assume the dash needle verifies ECT accuracy. A wrong-temperature aftermarket thermostat or trapped air can create a repeat failure. Never open the cooling system hot.",yearNotes:["D-, R-, K- and L-series Civics use different housings, thermostat specifications and bleeding details.","Turbo engines add charge cooling and different heat/load patterns but still require sensor plausibility first.","Hybrid engine stop/start reduces heat input by design; use its service/monitor procedure.","Cold weather and heater demand influence warm-up but do not excuse a repeatedly failed monitor."],faqs:[{question:"Is P0128 always the thermostat?",answer:"No. Sensor bias, low coolant, air and fan faults can imitate it."},{question:"Can I drive?",answer:"Usually briefly if coolant is full and temperature stable; stop for overheating."},{question:"Why does the gauge look normal?",answer:"It is intentionally damped; scan data has diagnostic resolution."},{question:"Can winter weather cause it?",answer:"It changes warm-up time, but the PCM accounts for enable conditions."},{question:"Will fuel economy fall?",answer:"It can because prolonged warm-up affects enrichment and emissions control."},{question:"Can I open the cap hot?",answer:"No. Pressurized coolant can cause severe burns."},{question:"Why compare ECT and IAT?",answer:"After a long soak both should approach ambient, exposing sensor bias before start."},{question:"What confirms repair?",answer:"Plausible cold values, normal regulation and no pending P0128."}],deepDive:[{heading:"The best first test costs no parts",paragraphs:["Before start, a thermostat cannot make the coolant sensor read far colder than the intake sensor.","Record both values and actual ambient rather than relying on a blue lamp or gauge position."]},{heading:"Road airflow can reveal leakage through the thermostat",paragraphs:["A thermostat unable to close may allow coolant temperature to drop as speed increases radiator airflow.","Graph speed, load and ECT together; a single idle reading misses this pattern."]},{heading:"Hybrid elapsed time is misleading",paragraphs:["The gasoline engine may stop while the car remains ready, so clock time does not equal combustion heat input.","Use Honda's hybrid-specific enable and service-mode instructions instead of a conventional Civic comparison."]}],sources:[serviceExpress,owners]}),

article({slug:"p0301",code:"P0301",title:"P0301 Code Honda Civic: Cylinder 1 Misfire Test Plan",description:"Diagnose Civic P0301 with correct cylinder identification, a controlled coil swap, injector tests and compression, plus the 2016–2018 1.5L branch.",definition:"Cylinder 1 Misfire Detected",severity:"Stop soon",driveAdvice:"Stop sustained driving when the MIL flashes or the Civic shakes strongly; raw fuel can rapidly overheat the catalyst. With a steady lamp and mild intermittent symptom, limit movement to diagnosis and avoid boost, high rpm and heavy load.",quickAnswer:"P0301 means the PCM attributed excessive misfire events to cylinder 1; it does not identify the failed component. Confirm cylinder 1 from the exact engine diagram, save cold/load counters, and inspect its plug while keeping all plugs labelled. Make one controlled coil swap and see whether the misfire follows. If it stays on cylinder 1, test injector command/delivery and compression/leak-down rather than replacing more ignition parts. Honda bulletin 19-038 supplies a special branch for VIN-eligible 2016–2018 Civic 1.5L P0300–P0304/P0172 cases and requires applicable 18-137 work first. Other engines and years follow normal diagnosis.",symptoms:[{key:"flash",label:"MIL flashes",response:"Stop loading the engine to protect the catalyst."},{key:"cold",label:"Cylinder 1 misfires cold",response:"Capture counts immediately and test injector leakage, ignition and sealing cold."},{key:"swap",label:"Misfire follows swapped coil",response:"Inspect boot/connector and replace the proved fault appropriately."},{key:"turbo",label:"2016–2018 1.5L with companion codes",response:"Check VIN/status and bulletin sequence before parts."}],causes:[{cause:"Cylinder 1 plug fouled, worn or cracked",evidence:"Abnormal gap/deposit/damage compared with neighbors",firstTest:"Labelled plug inspection"},{cause:"Coil, boot or connector fault",evidence:"Misfire follows controlled swap or circuit fails",firstTest:"One coil swap and loaded circuit test"},{cause:"Injector restriction, leakage or circuit fault",evidence:"Misfire stays while delivery/contribution differs",firstTest:"Injector command, balance and leak test"},{cause:"Compression, valve or timing problem",evidence:"Low relative/measured compression",firstTest:"Compression then leak-down"},{cause:"Covered 1.5L bulletin condition",evidence:"2016–2018 1.5L VIN/status and Honda sequence match",firstTest:"18-137 then 19-038 as applicable"}],freezeFrame:["Cylinder 1 and all-cylinder counts","RPM, load, coolant temperature and speed","Fuel correction and fuel-pressure data","Plug 1 deposits/gap and neighboring comparison","Compression/leak-down results","VIN, engine and 18-137/19-038 status"],steps:[{title:"Locate cylinder 1 correctly",detail:"Use the exact engine diagram before moving a coil or injector connector."},{title:"Preserve the condition",detail:"Cold and load misfires can disappear after warm-up or reset."},{title:"Read the plug",detail:"Photograph deposits, wetness, cracks and gap before replacement."},{title:"Make one coil swap",detail:"Follow the enhanced counter; if it stays at cylinder 1, stop swapping."},{title:"Test injector and sealing",detail:"Prove command/delivery and mechanical compression rather than guessing."},{title:"Check the limited Honda branch",detail:"Only eligible 2016–2018 1.5L cars use the bulletin path."},{title:"Verify twice",detail:"Confirm both cold start and safe-load operation with no pending P0301."}],dontReplace:"Do not replace all coils for one cylinder code, and do not promise bulletin coverage from model year alone. A new plug can temporarily mask injector leakage, oil fouling or low compression. Preserve the original plug as diagnostic evidence.",yearNotes:["2016–2018 1.5L: 19-038 lists P0301 and requires VIN/program checks plus applicable 18-137 repair first.","Older D/R/K engines and naturally aspirated 2.0L Civics are outside that remedy.","Direct-injection fuel lines require Honda depressurization and safety procedures.","Cylinder 1 location and access vary; rely on the engine-specific service diagram."],faqs:[{question:"Is P0301 always a bad coil?",answer:"No. Plug, injector, wiring, compression and valve/timing faults can cause it."},{question:"Can I drive?",answer:"Not with a flashing MIL or strong shaking."},{question:"Can I swap coils?",answer:"Yes, carefully, while monitoring whether the code/count follows."},{question:"What if it stays on cylinder 1?",answer:"Test injector delivery/circuit and compression/leak-down."},{question:"Does 19-038 cover every 1.5T?",answer:"No. It lists 2016–2018 and requires VIN/status confirmation."},{question:"Can valve clearance cause P0301?",answer:"Yes, if cylinder sealing is reduced, often with temperature dependence."},{question:"Should I clear first?",answer:"No. Save freeze data and counters before changing evidence."},{question:"What confirms repair?",answer:"No rising cylinder 1 count under the original cold/load condition."}],deepDive:[{heading:"One swap should answer one question",paragraphs:["Move the cylinder 1 coil to a known cylinder, then monitor enhanced counters under the same condition.","If the misfire remains, return the known-good coil and move to fuel/mechanical testing."]},{heading:"Plug appearance narrows the path",paragraphs:["Fuel wetness, oil ash, coolant-cleaned porcelain and excess gap do not mean the same thing.","Keep every plug in cylinder order; mixing them destroys the comparison."]},{heading:"Bulletin 19-038 is not the diagnosis for every Civic",paragraphs:["Honda restricts it to 2016–2018 1.5L vehicles and instructs technicians to check 18-137 first.","VIN eligibility and the specified inspection sequence determine whether its remedy applies."]}],sources:[misfireBulletin,serviceExpress,owners]}),
];
